-- Print document tracking for preparation lists.
-- The document itself remains generated by the client, while the order keeps
-- a small audit marker so operators can see that preparation was printed.
alter table public.orders
  add column if not exists preparation_print_status text not null default 'pending'
    check (preparation_print_status in ('pending', 'completed')),
  add column if not exists preparation_printed_at timestamptz;
